    "provider.desc": "Добавьте свою услугу в Ruumly — переезд, аренда фургона или прицепа, склад или уборка. Регистрация бесплатна, комиссии нет.",
    "provider.cta": "Стать партнёром",

    // Provider landing page
    "provPage.hero.subtitle": "Мы приводим вам клиентов, которые переезжают прямо сейчас — запросы от людей, которым нужны переезд (в том числе помощь с упаковкой), хранение, прицеп, фургон или уборка. Подключение бесплатное, комиссия 0%. Бронирования, договоры и платежи — опциональные инструменты.",
    "provPage.hero.cta": "Начать бесплатно",
