    "provider.stat3": "Доступ 24/7",
    "provPage.benefits.title": "Почему выбирают Ruumly?",
    "provPage.benefit1.title": "Новые клиенты",
    "provPage.benefit1.desc": "Привлекайте клиентов, которые ищут склады, переезды и прицепы в интернете.",
    "provPage.benefit2.title": "Удобное управление",
    "provPage.benefit2.desc": "В панели партнёра видны запросы, объявления, бронирования и аналитика там, где эти процессы включены.",
    "provPage.benefit3.title": "Гибкие условия",
    "provPage.benefit3.desc": "Начните бесплатно. Платные продвижения или дополнительные инструменты позже подключаются только по желанию и соглашению.",
    "provPage.benefit4.title": "Быстрый старт",
    "provPage.benefit4.desc": "Регистрация и добавление первого объявления занимает менее 10 минут.",
    "provPage.howItWorks.title": "Как это работает?",
    "provPage.step1.title": "Мы квалифицируем спрос",
    "provPage.step1.desc": "Клиент говорит, что ему нужно. Мы проверяем детали, услугу и сроки прежде, чем что-то дойдёт до вас.",
    "provPage.step2.title": "Направляем запрос вам",
