    "hiw.title": "Как работает Ruumly?",
    "hiw.subtitle": "Один запрос, до 3 предложений, ноль обзвонов. Вот как это работает.",
    "hiw.heroSearch": "Найти",
    "hiw.heroList": "Разместить склад",
    "hiw.stepsTitle": "Ваш путь в пять шагов",
    "hiw.stepsSubtitle": "Вы говорите, что нужно. Мы находим исполнителей.",
    "hiw.step1": "Найдите и сравните склады рядом",
    "hiw.step1desc": "Введите местоположение и просматривайте складские помещения местных партнёров. Сравнивайте площадь, цену и условия доступа на карте или в списке.",
    "hiw.step2": "Мы находим партнёров",
    "hiw.step2desc": "Мы изучаем ваш запрос и выбираем партнёров, которые действительно подходят — а не просто всех из списка.",
    "hiw.step3": "Вы получаете до 3 предложений",
    "hiw.step3desc": "Предложения приходят на почту по мере ответов партнёров. Спокойно сравните цены и условия.",
    "hiw.step4": "Выберите и договоритесь",
    "hiw.step4desc": "Общайтесь с выбранным партнёром напрямую и согласуйте детали. Для клиента Ruumly бесплатен и ничего не добавляет к цене.",
    "hiw.step5": "Получите доступ и заезжайте",
    "hiw.step5desc": "Получите подтверждение и инструкции по доступу от партнёра — привезите вещи и заезжайте в выбранную дату.",
    "hiw.whyTitle": "Почему Ruumly можно доверять?",
    "hiw.whySubtitle": "Ясность на каждом шаге — прежде чем вы на что-то соглашаетесь.",
    "hiw.feat1": "Значок проверенного партнёра",
    "hiw.feat1desc": "У партнёров, чьи регистрационные данные, IBAN и физический адрес мы подтвердили, в профиле стоит значок — сразу видно, кого именно мы проверили.",
    "hiw.feat2": "Настоящие предложения, а не реклама",
    "hiw.feat2desc": "Предложения приходят от партнёров, которые прочитали ваш запрос. Мы не продаём ваши контакты десяти компаниям.",
    "hiw.feat3": "Понятные условия",
    "hiw.feat3desc": "Объявления, запросы и при необходимости договор держат размер, цену и условия доступа в одном месте.",
    "hiw.feat4": "Наличие управляется партнёром",
    "hiw.feat4desc": "Партнёр сам управляет наличием, календарём и доступом, чтобы публичная информация оставалась актуальной.",
    "hiw.partnerBadge": "Для партнёров",
    "hiw.partnerTitle": "Разместите свой склад на Ruumly",
    "hiw.partnerDesc": "Есть свободное место для хранения или склад? Разместите его на Ruumly бесплатно и находите клиентов через карту и Google. Вы задаёте цены, наличие и выбираете: только запросы или также онлайн-бронирование.",
